{
	"schemaVersion": 1,
	"complete": false,
	"impacts": [
		{
			"requirement": "REQ-02",
			"classification": "changed",
			"breaking": false,
			"why": "CR-5 changes the journal write from a buffered write to an fsync; nothing outside the service can observe the difference except latency."
		},
		{
			"requirement": "REQ-03",
			"classification": "changed",
			"breaking": true,
			"why": "CR-1 extends the claim reference format with a regional prefix, changing its shape for the brokers who parse it."
		},
		{
			"requirement": "REQ-04",
			"classification": "changed",
			"breaking": false,
			"why": "CR-1 shortens the de-duplication window from twenty-four hours to four hours."
		},
		{
			"requirement": "REQ-08",
			"classification": "changed",
			"breaking": true,
			"why": "CR-4 adds two broker-visible statuses, awaiting_documents and withdrawn, to the poll vocabulary every integration switches on."
		},
		{
			"requirement": "REQ-11",
			"classification": "removed",
			"breaking": true,
			"why": "CR-2 retires the fax channel entirely; the two brokers still using it have nothing to fall back to."
		},
		{
			"requirement": "REQ-15",
			"classification": "added",
			"breaking": false,
			"why": "CR-3 adds a carrier capacity ceiling that refuses a submission once its handling queue is over its daily ceiling."
		},
		{
			"requirement": "REQ-16",
			"classification": "added",
			"breaking": false,
			"why": "CR-6 adds a broker-supplied loss adjuster nomination that is carried through to the handler."
		}
	]
}

